// Pure helpers are also used by the deployment tests.
export function experimentURL(id, view = "details", filters = new URLSearchParams()) {
  // Boolean view values remain compatible with links generated by the previous release.
  const selected = view === true || view === "results" ? "results" : "details";
  const params = new URLSearchParams({ view: selected });
  for (const [key, value] of new URLSearchParams(filters))
    if (key !== "view") params.set(key, value);
  return `#/experiments/${encodeURIComponent(id)}?${params}`;
}
export function overviewURL(category) {
  return `#/overview${category ? `?${new URLSearchParams({ category })}` : ""}`;
}
export function resourceURL(type, id) {
  if (!["dataset", "model"].includes(type)) throw new Error("Unknown resource type");
  return `#/${type}s/${encodeURIComponent(id)}`;
}
export function protocolURL(section) {
  return `#/protocol${section ? `?${new URLSearchParams({ section })}` : ""}`;
}
export function routeAnchorId(route) {
  if (route.page === "overview" && route.category) return `category-${route.category}`;
  if (route.page === "protocol" && route.section === "metrics") return "metric-definitions";
  return null;
}
export function parseRoute(hash) {
  const [path, query = ""] = hash.replace(/^#/, "").split("?");
  const params = new URLSearchParams(query);
  if (["", "/", "/overview", "overview"].includes(path)) {
    const category = params.get("category");
    return category
      ? /^[a-z0-9-]+$/.test(category)
        ? { page: "overview", category }
        : { page: "not-found" }
      : { page: "overview" };
  }
  if (["/protocol", "protocol"].includes(path)) {
    const section = params.get("section");
    return section
      ? section === "metrics"
        ? { page: "protocol", section }
        : { page: "not-found" }
      : { page: "protocol" };
  }
  const resource = /^\/(datasets|models)\/([a-z0-9-]+)$/.exec(path);
  if (resource) return { page: resource[1] === "datasets" ? "dataset" : "model", id: resource[2] };
  const match = /^\/experiments\/([a-z0-9-]+)$/.exec(path);
  if (match) {
    const view = params.get("view") || "details";
    if (!["details", "results"].includes(view)) return { page: "not-found" };
    return { page: "experiment", id: match[1], view, params };
  }
  return { page: "not-found" };
}
export function hasResults(experiment) {
  return (
    experiment.status === "published" &&
    (experiment.quantitative.length > 0 || experiment.qualitative.length > 0)
  );
}
export function resolveExperimentView(experiment, requested = "details") {
  return requested === "results" && hasResults(experiment) ? "results" : "details";
}
export function availability(experiment) {
  if (experiment.quantitative.length && experiment.qualitative.length)
    return "Quantitative & qualitative";
  if (experiment.quantitative.length) return "Quantitative results";
  if (experiment.qualitative.length) return "Qualitative results";
  return "Planned";
}
export function validateRegistry(registry) {
  if (
    registry.schema_version !== 1 ||
    !Array.isArray(registry.dimensions) ||
    !Array.isArray(registry.experiments)
  )
    throw new Error("Unsupported experiment registry");
  const dimensions = new Set(registry.dimensions.map((d) => d.id));
  if (dimensions.size !== registry.dimensions.length) throw new Error("Duplicate dimension");
  const ids = new Set();
  for (const entry of registry.experiments) {
    if (!/^[a-z0-9-]+$/.test(entry.id) || ids.has(entry.id))
      throw new Error("Invalid or duplicate experiment ID");
    ids.add(entry.id);
    if (!dimensions.has(entry.dimension)) throw new Error(`Unknown dimension: ${entry.dimension}`);
    if (!entry.name || !entry.description || !Array.isArray(entry.setup))
      throw new Error(`Incomplete experiment: ${entry.id}`);
    for (const field of ["quantitative", "qualitative", "illustrations", "sources"])
      if (!Array.isArray(entry[field])) throw new Error(`Missing ${field}: ${entry.id}`);
    for (const source of entry.sources)
      if (!registry.data_sources[source]) throw new Error(`Unknown data source: ${source}`);
    for (const module of entry.quantitative)
      if (!entry.sources.includes(module.source))
        throw new Error(`Unlinked quantitative source: ${entry.id}`);
    if (!["planned", "published"].includes(entry.status))
      throw new Error(`Invalid status: ${entry.id}`);
    const hasResults = entry.quantitative.length > 0 || entry.qualitative.length > 0;
    if ((entry.status === "published") !== hasResults)
      throw new Error(`Inconsistent availability: ${entry.id}`);
  }
  return registry;
}
